/**
 * Las piezas de la bienvenida (mensaje 154, nov-2026).
 *
 * Lo que Emilio aprobó en la maqueta: menos pantallas, que enseñen haciendo. Sin emojis (se ven distintos
 * en cada teléfono y nunca se ven diseñados): íconos dibujados en su cuadro. Títulos en Syne medidos
 * (28 a 32 px), texto en DM Sans, botones de piezas.tsx, colores de styles.css.
 */
import type { CSSProperties, ReactNode } from "react";

const TRAZO = { fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round" } as const;

/** Los íconos de la bienvenida, dibujados a 24 px. */
export const ICONOS = {
  libro: <><path d="M12 6.5C10.5 5 8 4.5 4 4.5v13c4 0 6.5.5 8 2 1.5-1.5 4-2 8-2v-13c-4 0-6.5.5-8 2z" /><path d="M12 6.5v13" /></>,
  microfono: <><rect x="9" y="2.5" width="6" height="12" rx="3" /><path d="M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21" /></>,
  mejora: <><circle cx="12" cy="12" r="8.5" /><path d="M9 12.5l2 2 4-4.5" /></>,
  equipo: <><circle cx="9" cy="8" r="3.2" /><path d="M3.5 19c.7-3 3-4.6 5.5-4.6s4.8 1.6 5.5 4.6" /><circle cx="17" cy="9" r="2.5" /><path d="M16 14.6c2.2.1 3.9 1.5 4.5 4.4" /></>,
  meta: <><circle cx="12" cy="12" r="8.5" /><circle cx="12" cy="12" r="4.5" /><circle cx="12" cy="12" r="1" fill="currentColor" /></>,
  escudo: <path d="M12 3l7 3v5.5c0 4.2-3 7.7-7 9.5-4-1.8-7-5.3-7-9.5V6z" />,
  puerta: <><path d="M6 21V4.5A1.5 1.5 0 0 1 7.5 3h9A1.5 1.5 0 0 1 18 4.5V21" /><path d="M3.5 21h17M14.5 12.5h.01" /></>,
  vuelta: <><path d="M4 12a8 8 0 0 1 13.7-5.6L20 8.5" /><path d="M20 4v4.5h-4.5" /><path d="M20 12a8 8 0 0 1-13.7 5.6L4 15.5" /><path d="M4 20v-4.5h4.5" /></>,
} as const;

export function Icono({ nombre, tam = 22 }: { nombre: keyof typeof ICONOS; tam?: number }) {
  return (
    <svg width={tam} height={tam} viewBox="0 0 24 24" aria-hidden {...TRAZO}>
      {ICONOS[nombre]}
    </svg>
  );
}

/** El nivel de experiencia como barras de señal (1, 2 o 3), en lugar de emojis. */
export function IconoNivel({ nivel, activo }: { nivel: 1 | 2 | 3; activo: boolean }) {
  const lleno = activo ? "var(--c-primary)" : "var(--c-text-soft)";
  return (
    <svg width={22} height={22} viewBox="0 0 24 24" aria-hidden>
      {[0, 1, 2].map((i) => (
        <rect key={i} x={4 + i * 6} y={16 - i * 5} width={4} height={4 + i * 5} rx={1.5} fill={i < nivel ? lleno : "var(--c-border-strong)"} />
      ))}
    </svg>
  );
}

/** La palabra CLOSER arriba de la bienvenida. */
export function Marca() {
  return <div style={{ fontFamily: "Syne, sans-serif", fontWeight: 800, fontSize: 18, letterSpacing: "0.06em", color: "var(--c-primary)" }}>CLOSER</div>;
}

export const estiloTitulo: CSSProperties = { margin: 0, fontFamily: "Syne, sans-serif", fontWeight: 700, fontSize: 30, lineHeight: 1.13, letterSpacing: "-0.02em", color: "var(--c-text)" };
export const estiloTexto: CSSProperties = { margin: 0, fontFamily: "'DM Sans', sans-serif", fontSize: 17, lineHeight: 1.5, color: "var(--c-text-soft)" };
export const estiloEtiqueta: CSSProperties = { fontFamily: "'DM Sans', sans-serif", fontSize: 13, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: "var(--c-text-2)" };

/** Un renglón con ícono en su cuadro, título y una línea de apoyo. */
export function FilaIcono({ icono, titulo, texto }: { icono: keyof typeof ICONOS; titulo: string; texto: string }) {
  return (
    <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
      <span aria-hidden style={{ width: 44, height: 44, flex: "none", borderRadius: "var(--r-icono)", background: "var(--c-elevated)", color: "var(--c-text-soft)", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Icono nombre={icono} />
      </span>
      <div style={{ display: "flex", flexDirection: "column", gap: 3, paddingTop: 2 }}>
        <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 16, fontWeight: 600, lineHeight: 1.35, color: "var(--c-text)" }}>{titulo}</span>
        <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 14, lineHeight: 1.45, color: "var(--c-text-2)" }}>{texto}</span>
      </div>
    </div>
  );
}

/** Una opción que se elige: tarjeta con ícono, título y descripción; la elegida en naranja. */
export function Opcion({ elegida, onClick, icono, titulo, texto }: { elegida: boolean; onClick: () => void; icono: ReactNode; titulo: string; texto: string }) {
  return (
    <button
      type="button"
      role="radio"
      aria-checked={elegida}
      onClick={onClick}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 14,
        width: "100%",
        minHeight: 68,
        padding: "10px 16px 10px 12px",
        borderRadius: 16,
        color: "var(--c-text)",
        textAlign: "left",
        cursor: "pointer",
        transition: "background 200ms ease, border-color 200ms ease",
        background: elegida ? "rgb(var(--c-primary-rgb) / 0.07)" : "var(--c-surface)",
        border: `1.5px solid ${elegida ? "var(--c-primary)" : "var(--c-border)"}`,
        WebkitTapHighlightColor: "transparent",
      }}
    >
      <span aria-hidden style={{ width: 44, height: 44, flex: "none", borderRadius: "var(--r-icono)", display: "flex", alignItems: "center", justifyContent: "center", transition: "background 200ms ease, color 200ms ease", background: elegida ? "rgb(var(--c-primary-rgb) / 0.14)" : "var(--c-elevated)", color: elegida ? "var(--c-primary)" : "var(--c-text-soft)" }}>
        {icono}
      </span>
      <span style={{ flex: 1, display: "flex", flexDirection: "column", gap: 2 }}>
        <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 16, fontWeight: 600 }}>{titulo}</span>
        <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 14, lineHeight: 1.4, color: "var(--c-text-2)" }}>{texto}</span>
      </span>
    </button>
  );
}

/** Una casilla que se marca, con su texto. «redonda»: una opción entre varias (se comporta como radio). */
export function Casilla({ marcada, onCambiar, children, redonda = false }: { marcada: boolean; onCambiar: (v: boolean) => void; children: ReactNode; redonda?: boolean }) {
  return (
    <button
      type="button"
      role={redonda ? "radio" : "checkbox"}
      aria-checked={marcada}
      onClick={() => onCambiar(!marcada)}
      style={{ width: "100%", display: "flex", gap: 12, alignItems: "flex-start", padding: "14px 16px", borderRadius: 16, border: "1px solid var(--c-border)", background: "transparent", color: "var(--c-text-soft)", textAlign: "left", cursor: "pointer", WebkitTapHighlightColor: "transparent" }}
    >
      <span aria-hidden style={{ width: 22, height: 22, flex: "none", marginTop: 1, borderRadius: redonda ? 11 : 7, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", transition: "background 150ms ease", ...(marcada ? { background: "var(--c-primary)" } : { border: "1.5px solid var(--c-border-strong)" }) }}>
        {marcada && <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="var(--c-bg)" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5" /></svg>}
      </span>
      <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 14, lineHeight: 1.45 }}>{children}</span>
    </button>
  );
}

/** El encabezado de las preguntas: regresar y la barra de avance en segmentos. */
export function EncabezadoPreguntas({ paso, total, onRegresar }: { paso: number; total: number; onRegresar?: () => void }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "44px 1fr 44px", alignItems: "center" }}>
      <button
        type="button"
        onClick={onRegresar}
        aria-label="Regresar"
        disabled={!onRegresar}
        style={{ width: 44, height: 44, marginLeft: -10, border: "none", borderRadius: 22, background: "transparent", color: "var(--c-text-soft)", display: "flex", alignItems: "center", justifyContent: "center", cursor: onRegresar ? "pointer" : "default", visibility: onRegresar ? "visible" : "hidden", padding: 0 }}
      >
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d="M15 5l-7 7 7 7" /></svg>
      </button>
      <div aria-label={`Pregunta ${paso} de ${total}`} style={{ display: "grid", gridTemplateColumns: `repeat(${total}, minmax(0, 1fr))`, gap: 6 }}>
        {Array.from({ length: total }, (_, k) => (
          <span key={k} style={{ height: 4, borderRadius: 2, transition: "background 300ms ease", background: k < paso ? "var(--c-primary)" : "var(--c-border)" }} />
        ))}
      </div>
      <span />
    </div>
  );
}

/**
 * Dónde va en la bienvenida (mensaje 159, Emilio): que siempre sepa en qué parte está y cuánto falta para
 * practicar. Son 4 partes; al terminar la 4ª, ya está en su mapa.
 */
export const PASOS_BIENVENIDA = ["Bienvenida", "Tu perfil", "Tu plan", "Cómo entrenas"] as const;

export function PasoBienvenida({ paso, style }: { paso: 1 | 2 | 3 | 4; style?: CSSProperties }) {
  return (
    <div style={{ ...estiloEtiqueta, ...style }}>
      Paso {paso} de {PASOS_BIENVENIDA.length} · {PASOS_BIENVENIDA[paso - 1]}
    </div>
  );
}

src/lib/giro-personal.ts.contenido:
/**
 * Lo que Closer le pregunta a quien entrena por su cuenta, y CUÁNDO (mensaje 157, nov-2026).
 *
 * Decisión de Emilio: cada dato se pide «justo a tiempo», antes del primer nodo que lo necesita, con su
 * porqué. Así el vendedor no llena un formulario largo al entrar (y no se va), y cada respuesta llega
 * cuando ya se ve para qué sirve. Son las mismas preguntas del onboarding del manager (PREGUNTAS), dichas a
 * quien vende él mismo. Todo lo que contesta lo puede ver y editar en «Tu negocio».
 *
 * Dónde se pide cada cosa y por qué ahí:
 *   · Antes de la 1ª práctica (1.2): qué vende, a quién, de qué tamaño, y cómo vende y con qué trato —
 *     el trato y el canal cambian al cliente desde la primera plática.
 *   · Antes del 3.8: su cartera. Hasta el 3.6 todos los clientes son nuevos (nodes.tipo_cliente); el 3.8 es el
 *     primero con un cliente que ya le compra.
 *   · Antes del 4.1: lo que ofrece y lo que su empresa no le deja prometer — presentar y las balas necesitan
 *     hechos reales suyos, y el evaluador tiene que saber qué no puede prometer.
 *   · Antes del 4.9: cómo maneja el precio — ahí el cliente empieza a negociar.
 *   · Antes del 5.6: lo que más le dicen sus clientes — su primera práctica de objeciones.
 *
 * Todo aquí es puro: lo usan la práctica, «Tu negocio» y las pruebas.
 */
import { PREGUNTAS, preguntaCompleta, type Pregunta, type Respuestas } from "@/lib/onboarding-questions";

export interface TextoPersonal {
  titulo: string;
  sub?: string;
  porQue: string;
}

/** Las 9 preguntas del manager, dichas a quien vende él mismo (las del manager hablan de «tus vendedores»). */
export const TEXTO_PERSONAL: Record<string, TextoPersonal> = {
  p1_que_venden: {
    titulo: "¿Qué vendes?",
    sub: "Tus productos principales. No hace falta todo el catálogo.",
    porQue: "Tu cliente solo habla de lo que tú vendes. Closer nunca inventa productos.",
  },
  p2_clientes: {
    titulo: "¿Qué hacen tus clientes con lo que les vendes?",
    sub: "Marca todo lo que aplique.",
    porQue: "Así tu cliente tiene el negocio y los problemas de los tuyos.",
  },
  p3_monto: {
    titulo: "¿Cuánto te compra un cliente al mes?",
    sub: "Marca todos los que tengas.",
    porQue: "Practicas con clientes del tamaño de los tuyos.",
  },
  p5_canal: {
    titulo: "¿Cómo vendes?",
    sub: "Marca todo lo que aplique.",
    porQue: "Tu cliente te habla como te hablan los tuyos.",
  },
  p4_cartera: {
    titulo: "¿Visitas más clientes que ya te compran, o nuevos?",
    porQue: "Practicas con clientes nuevos y con los de siempre, como en tu día.",
  },
  p6_ofrecen: {
    titulo: "¿Qué ofreces?",
    sub: "Marca todo lo que ofreces.",
    porQue: "Al presentar, usas solo lo que de verdad ofreces.",
  },
  p9_restricciones: {
    titulo: "¿Qué no te deja prometer tu empresa?",
    sub: "Closer ya te prohíbe mentir. Aquí van las reglas de tu empresa.",
    porQue: "Closer te avisa si prometes algo que no puedes cumplir.",
  },
  p7_precio: {
    titulo: "¿Cómo manejas el precio?",
    porQue: "Practicas solo con los descuentos y plazos que de verdad das.",
  },
  p8_negativos: {
    titulo: "¿Esto te dicen tus clientes?",
    sub: "Closer las propuso para tu giro. Deja marcadas las que sí escuchas.",
    porQue: "Practicas con las objeciones que te dicen de verdad.",
  },
};

export interface Puerta {
  id: string;
  /** El primer nodo que necesita estas respuestas: se piden al empezar su práctica (o una posterior). */
  antesDe: string;
  titulo: string;
  texto: string;
  preguntas: string[];
}

export const PUERTAS: Puerta[] = [
  {
    id: "cliente",
    antesDe: "1.2",
    titulo: "Tu cliente está por llegar",
    texto: "Cuéntanos qué vendes y cómo. Así tu cliente se parece a los tuyos.",
    preguntas: ["p1_que_venden", "p2_clientes", "p3_monto", "p5_canal"],
  },
  {
    id: "cartera",
    antesDe: "3.8",
    titulo: "Llega un cliente que ya te compra",
    texto: "Desde aquí también visitas clientes que ya te compran, como en tu ruta.",
    preguntas: ["p4_cartera"],
  },
  {
    id: "oferta",
    antesDe: "4.1",
    titulo: "Vas a presentar",
    texto: "Cuéntanos qué ofreces y qué no puedes prometer. Así presentas con lo que de verdad tienes.",
    preguntas: ["p6_ofrecen", "p9_restricciones"],
  },
  {
    id: "precio",
    antesDe: "4.9",
    titulo: "Tu cliente va a negociar",
    texto: "Cuéntanos cómo manejas el precio. Así practicas solo con lo que de verdad puedes dar.",
    preguntas: ["p7_precio"],
  },
  {
    id: "objeciones",
    antesDe: "5.6",
    titulo: "Llegan las objeciones",
    texto: "Marca lo que te dicen tus clientes. Así practicas con sus palabras.",
    preguntas: ["p8_negativos"],
  },
];

/** Las preguntas de las puertas, en el orden en que se piden. */
export const ORDEN_PREGUNTAS = PUERTAS.flatMap((p) => p.preguntas);

export const preguntaPorId = (id: string): Pregunta => {
  const p = PREGUNTAS.find((x) => x.id === id);
  if (!p) throw new Error(`pregunta desconocida: ${id}`);
  return p;
};

/** Ordena ids de nodo como el mapa: 2.7 < 2.7b < 2.7c < 2.8 < 2.10. */
export function compararNodos(a: string, b: string): number {
  const parte = (id: string) => {
    const m = /^(\d+)\.(\d+)([a-z]*)$/.exec(id);
    return m ? [Number(m[1]), Number(m[2]), m[3]] as const : ([999, 999, id] as const);
  };
  const [aw, an, as] = parte(a);
  const [bw, bn, bs] = parte(b);
  if (aw !== bw) return aw - bw;
  if (an !== bn) return an - bn;
  return as < bs ? -1 : as > bs ? 1 : 0;
}

/**
 * Las respuestas de antes del mensaje 157 no se guardaban (solo el cerebro). Si el cerebro ya dice qué vende
 * pero no hay respuestas, las 3 primeras se dan por contestadas: no se le vuelven a pedir.
 */
function yaEstabaContestada(id: string, r: Respuestas, cerebro: unknown): boolean {
  if (!["p1_que_venden", "p2_clientes", "p3_monto"].includes(id)) return false;
  if (Object.keys(r).some((k) => !k.startsWith("__"))) return false;
  let c: any = cerebro;
  if (typeof c === "string") {
    try { c = JSON.parse(c); } catch { return false; }
  }
  return typeof c?.PRODUCTOS_ACTIVOS === "string" && c.PRODUCTOS_ACTIVOS.trim().length > 0;
}

/** Llaves internas de respuestas_giro (no son respuestas): qué preguntas ya vio y lo que Closer propuso. */
export const VISTAS = "__vistas";
export const PROPUESTAS = { negativos: "__propuestas_negativos", restricciones: "__propuestas_restricciones" } as const;

export const vistas = (r: Respuestas): string[] => (Array.isArray(r[VISTAS]) ? (r[VISTAS] as string[]) : []);

/**
 * ¿Ya la contestó? Cuenta haberla visto y guardado, aunque deje vacío lo opcional (p. ej. sus reglas):
 * no se le vuelve a pedir; si quiere, la completa en «Tu negocio».
 */
export function contestada(id: string, r: Respuestas, cerebro?: unknown): boolean {
  return vistas(r).includes(id) || yaEstabaContestada(id, r, cerebro);
}

/** ¿Tiene lo mínimo para avanzar? (las reglas del manager: preguntaCompleta) */
export const completa = (id: string, r: Respuestas): boolean => preguntaCompleta(preguntaPorId(id), r);

/**
 * La puerta que toca antes de practicar este nodo, con solo las preguntas que faltan; o null.
 * Toca si el nodo es el de la puerta o uno posterior (si ya pasó de largo, se pide en la siguiente práctica).
 */
export function puertaPendiente(nodeId: string, r: Respuestas, cerebro?: unknown): Puerta | null {
  for (const p of PUERTAS) {
    if (compararNodos(nodeId, p.antesDe) < 0) break;
    const faltan = p.preguntas.filter((q) => !contestada(q, r, cerebro));
    if (faltan.length) return { ...p, preguntas: faltan };
  }
  return null;
}

/** Lo que se guarda: sin campos vacíos, y con estas preguntas marcadas como vistas. */
export function respuestasParaGuardar(r: Respuestas, vistasAhora: string[]): Respuestas {
  const out: Respuestas = {};
  for (const [k, v] of Object.entries(r)) {
    const vacio = Array.isArray(v) ? v.length === 0 : typeof v !== "string" || v.trim() === "";
    if (!vacio) out[k] = v;
  }
  out[VISTAS] = Array.from(new Set([...vistas(r), ...vistasAhora]));
  return out;
}

src/lib/guia-mapa.ts.contenido:
/**
 * El texto del globo «Empieza aquí» (mensaje 155, nov-2026).
 *
 * Emilio: quien descarga Closer para practicar con su voz y se encuentra tarjetas y un quiz puede pensar
 * que no era lo que esperaba. El globo le dice qué tipo de nodo tiene enfrente y cuándo llega su
 * práctica con voz. Se calcula del mapa real (node_type), no se escribe a mano: si el contenido cambia,
 * el globo sigue diciendo la verdad.
 */
export type NodoGuia = { node_type?: string | null; minutos_estimados: number | null };

const ORDINAL = ["", "primer", "segundo", "tercer", "cuarto", "quinto", "sexto", "séptimo", "octavo", "noveno", "décimo"];

/** Un nodo «de teoría» solo tiene tarjetas y quiz; los demás terminan con una práctica con voz. */
export const esTeoria = (n: NodoGuia) => n.node_type === "knowledge";

export function textoGuiaMapa(ordenados: NodoGuia[], activo: number, esNuevo: boolean): string {
  // Mensaje 159: frases cortas y fáciles. Qué es este nodo, cuánto toma y cuándo practica con un cliente.
  const n = ordenados[activo];
  if (!n) return "";
  const min = n.minutos_estimados ? ` ${n.minutos_estimados} minutos.` : "";
  if (!esTeoria(n)) return `Aquí practicas con un cliente.${min ? ` Toma${min}` : ""}`;
  let texto = `Teoría corta:${min || " tarjetas y un quiz."}`;
  const siguiente = ordenados.findIndex((x, k) => k > activo && !esTeoria(x));
  if (siguiente < 0) return texto;
  const posicion = siguiente + 1; // en el mapa completo, contando desde 1
  if (siguiente === activo + 1) texto += esNuevo ? " En el siguiente nodo practicas con tu primer cliente." : " En el siguiente nodo practicas con un cliente.";
  else if (esNuevo && posicion < ORDINAL.length) texto += ` En el ${ORDINAL[posicion]} nodo practicas con tu primer cliente.`;
  else texto += ` En ${siguiente - activo} nodos practicas con un cliente.`;
  return texto;
}

